{
  "name": "@bergetai/guardrails-md",
  "version": "0.8.0",
  "description": "GUARDRAILS.md gate for opencode, pi and Claude Code (hooks module): a System One decision model (TypeSafe Jev) judges every bash command before it runs — destructive / credentials / GUARDRAILS.md policy",
  "type": "module",
  "exports": {
    ".": "./adapters/opencode.ts",
    "./opencode": "./adapters/opencode.ts",
    "./server": "./adapters/opencode.ts",
    "./pi": "./adapters/pi.ts"
  },
  "files": [
    "core.ts",
    "adapters/opencode.ts",
    "adapters/pi.ts",
    ".claude-plugin/plugin.json",
    "hooks/hooks.json",
    "hooks/register.ts",
    "README.md",
    "guardrails.example.md"
  ],
  "scripts": {
    "test:claude": "scripts/test-claude.sh"
  },
  "pi": {
    "extensions": [
      "./adapters/pi.ts"
    ]
  },
  "keywords": [
    "opencode",
    "opencode-plugin",
    "pi",
    "pi-package",
    "systemone",
    "safety",
    "guardrails",
    "bash",
    "security"
  ],
  "license": "MIT",
  "publishConfig": {
    "access": "public"
  },
  "repository": {
    "type": "git",
    "url": "git+https://github.com/berget-ai/guardrails-md.git"
  },
  "bugs": {
    "url": "https://github.com/berget-ai/guardrails-md/issues"
  },
  "homepage": "https://github.com/berget-ai/guardrails-md#readme",
  "dependencies": {
    "@typesafe-ai/sdk": "^0.6.0"
  },
  "peerDependencies": {
    "@earendil-works/pi-coding-agent": "*"
  },
  "peerDependenciesMeta": {
    "@earendil-works/pi-coding-agent": {
      "optional": true
    }
  },
  "devDependencies": {
    "vitest": "^5.0.3"
  }
}
